  // Flow animation stays above the grid but below cards, so active edges never draw over images.
  stage.add(gridLayer, flowLayer, mainLayer, portLayer, marqueeLayer, dragLayer);
  // #49 核武：点阵画在独立 HTML 背景画布（绕开 Konva 图层画布裁剪问题）
  bgCanvas = document.createElement('canvas');
  bgCanvas.style.cssText = 'position:absolute;left:0;top:0;pointer-events:none;';
  wrap().insertBefore(bgCanvas, mount());
  if (!document.getElementById('node-inspector')) {
    const inspector = document.createElement('div');
    inspector.id = 'node-inspector';
    inspector.style.display = 'none';
    wrap().appendChild(inspector);
  }

  tr = new Konva.Transformer({
    anchorSize: 6, anchorCornerRadius: 3, anchorStrokeWidth: 1,
    rotateEnabled: false, borderEnabled: false,
    enabledAnchors: ['top-left', 'top-right', 'bottom-left', 'bottom-right'],
    ignoreStroke: true,
    padding: 2,
    anchorStroke: cssVar('--panel') || '#ffffff',
    anchorFill: SELECT_BLUE,
    keepRatio: true
  });
