  const safeLeft = viewX + Math.min(92 / Math.max(0.25, scale), viewW * 0.18);
  const safeTop = viewY + 18 / Math.max(0.25, scale);
  const safeRight = viewX + viewW - 18 / Math.max(0.25, scale);
