  if (!gl) return null;
  const vertexSource = 'attribute vec2 p;varying vec2 v;void main(){v=p*.5+.5;gl_Position=vec4(p,0.,1.);}';
  const fragmentSource = `precision highp float;
    varying vec2 v;
    uniform sampler2D tex;
    uniform vec2 res;
    uniform float yaw;
    uniform float pitch;
    uniform float fov;
    const float PI=3.141592653589793;
    void main(){
      vec2 p=v*2.-1.;
      p.x*=res.x/res.y;
      vec3 d=normalize(vec3(p.x*tan(fov*.5),p.y*tan(fov*.5),-1.));
      float cy=cos(yaw),sy=sin(yaw),cp=cos(pitch),sp=sin(pitch);
      d=vec3(cy*d.x+sy*d.z,d.y,-sy*d.x+cy*d.z);
      d=vec3(d.x,cp*d.y-sp*d.z,sp*d.y+cp*d.z);
      float lon=atan(d.x,-d.z);
      float lat=asin(clamp(d.y,-1.,1.));
      vec2 uv=vec2(lon/(2.*PI)+.5,.5-lat/PI);
      gl_FragColor=texture2D(tex,uv);
    }`;
