        gl.useProgram(program);
        gl.activeTexture(gl.TEXTURE0);
        gl.bindTexture(gl.TEXTURE_2D, texture);
        gl.uniform1i(gl.getUniformLocation(program, 'tex'), 0);
        gl.uniform2f(gl.getUniformLocation(program, 'res'), canvas.width, canvas.height);
        gl.uniform1f(gl.getUniformLocation(program, 'yaw'), Number(options.yaw) || 0);
        gl.uniform1f(gl.getUniformLocation(program, 'pitch'), Number(options.pitch) || 0);
