async function applyMaterialReference(room, dataURL, label, slotKey) {
  if (!project) throw new Error('请先打开项目');
  if (!dataURL) throw new Error('没有可用的图片');
  const before = clonePlain(materialStore);
  const saved = await ipcRenderer.invoke('img:write', { projectPath: project.path, dataURL });
  if (!saved || !saved.ok) throw new Error((saved && saved.msg) || '参考图保存失败');
  const sampledColor = slotKey ? await sampleMaterialReferenceColor(saved.name) : '';
  const next = Object.assign({}, materialsForRoom(room) || {});
  const ref = { src: saved.name, name: label || '材质参考图', w: saved.w || 0, h: saved.h || 0, at: Date.now() };
  if (slotKey) {
    next[slotKey] = Object.assign({}, next[slotKey] || {}, {
      ref,
      color: sampledColor || '',
      colorTouched: false,
      tintFollow: false,
      tintStrength: materialTintStrength(next[slotKey]),
      tintHue: 0,
      tintSaturation: 1,
      tintLightness: 0
    });
  } else {
    next.reference = ref;
  }
  materialStore[room] = next;
  const after = clonePlain(materialStore);
  pushUndoCommand({
    kind: 'command',
    undo() { materialStore = clonePlain(before); refreshMaterialNodes(room); },
    redo() { materialStore = clonePlain(after); refreshMaterialNodes(room); }
  });
  refreshMaterialNodes(room);
  afterMutation(slotKey ? '材质参考图已更新' : '通用材质参考图已更新');
  return ref;
}
