async function applyLightExteriorDataURL(k, dataURL, label) {
  if (!k || k.gwType !== 'light' || !dataURL) throw new Error('外景图片不可用');
  if (!project) throw new Error('请先打开项目');
  const saved = await ipcRenderer.invoke('img:write', { projectPath: project.path, dataURL });
  if (!saved || !saved.ok) throw new Error((saved && saved.msg) || '外景图保存失败');
  const before = clonePlain(k.gwLight || defaultLightConfig());
  let analysis = null;
  try {
    if (window.GWReferenceAnalysis) analysis = await window.GWReferenceAnalysis.analyze(dataURL);
  } catch (error) {}
  let linkedLight = {};
  if (analysis) {
    const rgb = /^#([0-9a-f]{6})$/i.exec(analysis.average || '');
    const channels = rgb ? [0, 2, 4].map(offset => parseInt(rgb[1].slice(offset, offset + 2), 16)) : [128, 128, 128];
    const luminance = channels[0] * 0.2126 + channels[1] * 0.7152 + channels[2] * 0.0722;
    linkedLight = {
      intensity: Math.max(28, Math.min(78, Math.round(18 + luminance * 0.66))),
      temperature: analysis.cooling ? 5800 : (analysis.tone === '偏暖' ? 4100 : 5000),
      softness: analysis.cooling ? 64 : 54,
      presetId: 'custom',
      name: '外景联动光影'
    };
  }
  k.gwLight = Object.assign(defaultLightConfig(), k.gwLight || {}, {
    ...linkedLight,
    exteriorPreset: 'custom',
    exteriorName: label || '自定义外景',
    exteriorPrompt: '',
    exterior: {
      src: saved.name,
      name: label || '自定义外景',
      w: saved.w || 0,
      h: saved.h || 0,
      at: Date.now(),
      linkedLight: Object.assign({}, linkedLight),
      analysis: analysis ? {
        summary: analysis.summary,
        average: analysis.average,
        tone: analysis.tone,
        cooling: analysis.cooling,
        shadows: analysis.shadows,
        midtones: analysis.midtones,
        highlights: analysis.highlights
      } : null
    }
  });
  const after = clonePlain(k.gwLight);
  pushUndoCommand({
    kind: 'command',
    undo() { k.gwLight = clonePlain(before); refreshLightNodes(); ensurePersistentNodePanel(k, true); },
    redo() { k.gwLight = clonePlain(after); refreshLightNodes(); ensurePersistentNodePanel(k, true); }
  });
  scheduleSave();
  refreshLightNodes();
  refreshGeneratorPanelsForLight(k);
  ensurePersistentNodePanel(k, true);
  afterMutation('窗外外景已更新');
  return k.gwLight.exterior;
}
async function assignAssetImagesToLightExterior(images, nodeId) {
  const target = nodes.find(node => node.id === nodeId);
  const image = Array.isArray(images) ? images.find(Boolean) : null;
  if (!target || !target.konva || target.konva.gwType !== 'light') throw new Error('找不到目标光影节点');
  if (!image) throw new Error('资产中没有可用图片');
  let dataURL = image.dataURL || '';
  if (!dataURL && image.file) dataURL = await readAssetImageFile(image.file);
  if (!dataURL) dataURL = image.preview || '';
  if (!dataURL) throw new Error('资产图片原文件不可用');
  return applyLightExteriorDataURL(target.konva, dataURL, image.label || image.name || '资产库外景图');
}
async function hydrateLightExteriorPreview(panel, light) {
  const image = panel.querySelector('[data-light-exterior-image]');
  const ref = light && light.exterior;
  if (!image || !ref || !ref.src) return;
  try {
    const dataURL = /^(?:data:image\/|blob:|https?:\/\/)/i.test(ref.src)
      ? ref.src
      : await getImageRuntime().readDataURL(ref.src);
    if (!dataURL || !panel.isConnected) return;
    image.src = dataURL;
    image.style.display = 'block';
    const placeholder = panel.querySelector('[data-light-exterior-placeholder]');
    if (placeholder) placeholder.style.display = 'none';
  } catch (error) {
    console.warn('[light] 外景预览读取失败', error && error.message);
  }
}
