async function analyzePlanStyleReference(k, styleRecord) {
  if (!k || !styleRecord || !styleRecord.konva) return null;
  const sourceNodeId = styleRecord.konva.gwId;
  if (k.gwPlanStyleAnalysis && k.gwPlanStyleAnalysis.sourceNodeId === sourceNodeId) {
    return k.gwPlanStyleAnalysis;
  }
  if (k.gwPlanStyleAnalysisPending === sourceNodeId) return null;
  k.gwPlanStyleAnalysisPending = sourceNodeId;
  try {
    if (!window.GWReferenceAnalysis) throw new Error('参考图分析模块未加载');
    const dataURL = await referenceDataURLForNode(styleRecord.konva, 768);
    if (!dataURL) throw new Error('参考图读取失败');
    const analysis = await window.GWReferenceAnalysis.analyze(dataURL);
    if (!analysis) throw new Error('参考图没有可分析的配色');
    k.gwPlanStyleAnalysis = {
      sourceNodeId,
      summary: analysis.summary,
      dominant: Array.isArray(analysis.dominant) ? analysis.dominant.slice(0, 5) : [],
      average: analysis.average,
      tone: analysis.tone,
      cooling: analysis.cooling
    };
  } catch (error) {
    k.gwPlanStyleAnalysis = {
      sourceNodeId,
      error: error.message || '参考图分析失败',
      dominant: []
    };
  } finally {
    if (k.gwPlanStyleAnalysisPending === sourceNodeId) k.gwPlanStyleAnalysisPending = '';
    const activeStyle = graphInputNodeForPort(k, 'style');
    if (activeStyle && activeStyle.konva && activeStyle.konva.gwId === sourceNodeId) {
      ensurePersistentNodePanel(k, true);
    }
  }
  return k.gwPlanStyleAnalysis;
}
