function expectedGeneratorOutputSize(params, sourceK) {
  const aspect = params && params.aspect;
  const known = {
    '1:1': 1,
    '16:9': 16 / 9,
    '9:16': 9 / 16,
    '4:3': 4 / 3,
    '3:2': 3 / 2,
    '2:3': 2 / 3,
    '3:4': 3 / 4,
    '4:5': 4 / 5,
    '5:4': 5 / 4,
    '2:1': 2,
    '21:9': 21 / 9
  };
  let ratio = known[aspect];
  if (!ratio) {
    const w = sourceK ? (sourceK.gwOw || sourceK.width() || 16) : 16;
    const h = sourceK ? (sourceK.gwOh || sourceK.height() || 9) : 9;
    ratio = w / Math.max(1, h);
  }
  ratio = Math.max(0.55, Math.min(1.9, ratio));
  return { w: Math.max(NODE_CARD_MIN_W, Math.round(NODE_CARD_H * ratio)), h: NODE_CARD_H };
}
