  (records || []).forEach(record => {
    const k = record && record.konva;
    if (!k) return;
    if (k.gwType === 'tool' && k.gwToolKind === 'mark') {
      (k.gwMarkCameras || []).forEach(camera => {
        const source = camera.sourceId ? nodes.find(node => node.id === camera.sourceId) : null;
        if (!source || !source.konva) return;
        const existing = expanded.find(item => item.konva === source.konva);
        if (existing) {
          markBySource.set(source.konva.gwId, { group: k, camera });
          return;
        }
        expanded.push(source);
        markBySource.set(source.konva.gwId, { group: k, camera });
      });
      return;
    }
    if (!expanded.some(item => item.konva === k)) expanded.push(record);
  });
