  if (targets.length < 2) { toast('至少选择两个节点，或选中一个连通的节点网络', true); return; }
  const anchor = targets.includes(picked[0]) ? picked[0] : targets[0];
  const ids = new Set(targets.map(k => k.gwId));
  const state = serialize();
  const records = state.nodes.filter(rec => ids.has(rec.id)).map(rec => JSON.parse(JSON.stringify(rec)));
  if (records.length < 2) { toast('可合并的节点不足', true); return; }
  const minX = Math.min(...records.map(rec => rec.x || 0));
  const minY = Math.min(...records.map(rec => rec.y || 0));
  records.forEach(rec => {
    rec.x = Math.round((rec.x || 0) - minX);
    rec.y = Math.round((rec.y || 0) - minY);
  });
  const touchedEdges = (state.edges || [])
    .filter(edge => ids.has(edge.from) || ids.has(edge.to))
    .map(edge => JSON.parse(JSON.stringify(edge)));
  const core = window.GWGraphCore;
  const edges = core && core.collapsedInternalEdges
    ? core.collapsedInternalEdges(touchedEdges, ids)
    : touchedEdges.filter(edge => ids.has(edge.from) && ids.has(edge.to));
  const boundaryEdges = core && core.collapsedBoundaryEdges
    ? core.collapsedBoundaryEdges(touchedEdges, ids)
    : touchedEdges.filter(edge => ids.has(edge.from) !== ids.has(edge.to));
  let thumb = '';
  for (const k of targets) {
    const src = nodeMediaSrc(k);
    if (src) { thumb = src; break; }
  }
  const occupied = nodes
    .filter(rec => rec.konva && !ids.has(rec.id))
    .map(rec => {
      const k = rec.konva;
      const size = layoutNodeSize(k);
      return { x: k.x(), y: k.y(), w: size.w, h: size.h };
    });
  const spot = findFreeWorldSpot(anchor.x(), anchor.y(), COLLAPSED_W, COLLAPSED_H, occupied);
  pushUndo();
  removeEdgesForNodeIds(ids);
  const entries = targets
    .map(k => ({ k, index: nodes.findIndex(rec => rec.konva === k), rec: nodes.find(rec => rec.konva === k) }))
    .filter(entry => entry.rec);
  detachNodeEntries(entries);
