    (k.gwFavorite ? ' <span class="asset-favorite">收藏</span>' : '') +
    (k.gwStar ? ' <span class="star">★</span>' : '') +
    '</div><div class="s">' + (isCard ? '变体卡 · 点击定位' : '原始 ' + (k.gwOw || Math.round(k.width())) + '×' + (k.gwOh || Math.round(k.height()))) + roomText + (isRef ? ' · 空间参考' : '') + '</div></div>';
  if (!thumb) hydrateNodeListThumb(el.querySelector('img'), n);
