function getRuntimeStats() {
  const byType = {};
  nodes.forEach(n => { byType[n.type] = (byType[n.type] || 0) + 1; });
  const mem = performance && performance.memory ? {
    usedMB: Math.round(performance.memory.usedJSHeapSize / 1048576),
    totalMB: Math.round(performance.memory.totalJSHeapSize / 1048576),
    limitMB: Math.round(performance.memory.jsHeapSizeLimit / 1048576)
  } : null;
  return {
    nodes: nodes.length,
    edges: graphStore ? graphStore.edges.size : 0,
    byType,
    selected: selection().length,
    running: nodes.filter(node => node.konva && node.konva.gwRunning).length,
    pending: pendingVisuals.length,
    dirty: canvasDirty,
    undo: undoStack.length,
    redo: redoStack.length,
    zoom: stage ? Math.round(stage.scaleX() * 100) : 0,
    viewport: stage ? { w: Math.round(stage.width()), h: Math.round(stage.height()) } : null,
    culling: window.GWSceneRuntime ? window.GWSceneRuntime.stats() : null,
    bitmapCache: nodes.reduce((count, record) => {
      const k = record && record.konva;
      return count + (k && typeof k.isCached === 'function' && k.isCached() ? 1 : 0);
    }, 0),
    images: getImageRuntime() ? getImageRuntime().stats() : null,
    save: { snapshot: !!savedSnapshot, snapshotNodes: savedSnapshot ? savedSnapshot.nodes.size : 0, api: saveApiVersion },
    memory: mem,
    savedAt: new Date().toISOString()
  };
}
function getModelUsage() {
  const counts = {};
  const add = engineId => {
    if (!engineId) return;
    counts[engineId] = (counts[engineId] || 0) + 1;
  };
  if (curRecipe && curRecipe.engineId) add(curRecipe.engineId);
  nodes.forEach(record => {
    const k = record && record.konva;
    if (!k) return;
    if ((record.type === 'generator' || record.type === 'param') && k.gwParams) add(k.gwParams.engineId);
    if (record.type === 'tool' && k.gwInpaintEngine) add(k.gwInpaintEngine);
    if (record.type === 'soft' && k.gwSoft) add(k.gwSoft.visionEngine);
  });
  return Object.keys(counts)
    .sort((a, b) => counts[b] - counts[a])
    .map(engineId => ({ engineId, count: counts[engineId] }));
}
