function assetPreviewPlaceholder(title, subtitle, kind) {
  const canvas = document.createElement('canvas');
  canvas.width = 720; canvas.height = 420;
  const ctx = canvas.getContext('2d');
  const gradient = ctx.createLinearGradient(0, 0, 720, 420);
  gradient.addColorStop(0, '#f3eee5');
  gradient.addColorStop(1, '#dbe3e5');
  ctx.fillStyle = gradient;
  ctx.fillRect(0, 0, 720, 420);
  ctx.fillStyle = SELECT_BLUE;
  ctx.fillRect(48, 48, 54, 5);
  ctx.fillStyle = '#272522';
  ctx.font = '700 42px "GIWIN Serif",serif';
  ctx.fillText(fitCanvasText(ctx, title || (kind === 'workflow' ? '工作流资产' : '通用资产'), 620), 48, 126);
  ctx.fillStyle = '#68635d';
  ctx.font = '400 18px "GIWIN Sans",sans-serif';
  const lines = wrapCanvasTextLines(ctx, subtitle || '', 620, 4);
  lines.forEach((line, index) => ctx.fillText(line, 48, 174 + index * 30));
  ctx.fillStyle = '#8f8981';
  ctx.font = '500 12px "GIWIN Sans",sans-serif';
  ctx.fillText(kind === 'workflow' ? 'GIWIN WORKFLOW ASSET' : 'GIWIN REUSABLE ASSET', 48, 370);
  return canvas.toDataURL('image/jpeg', 0.86);
}
function buildWorkflowPreviewDataURL(graph, title) {
  if (!graph || !Array.isArray(graph.nodes) || !graph.nodes.length) {
    return assetPreviewPlaceholder(title, '还没有节点内容', 'workflow');
  }
  const canvas = document.createElement('canvas');
  canvas.width = 720; canvas.height = 420;
  const ctx = canvas.getContext('2d');
  ctx.fillStyle = '#f5f1ea';
  ctx.fillRect(0, 0, 720, 420);
  const defaultSize = node => ({
    w: node.w || node.gwW || ({ generator: 430, image: 430, layout: 240, soft: 240, material: 240, light: 240, param: 240, variant: 240, tool: 240 }[node.type] || 240),
    h: node.h || node.gwH || ({ generator: 190, layout: 160, soft: 150, material: 140, light: 140, param: 130, variant: 150, image: 130, tool: 130 }[node.type] || 120)
  });
  const rects = graph.nodes.map(node => {
    const size = defaultSize(node);
    return { node, x: Number(node.x) || 0, y: Number(node.y) || 0, w: size.w, h: size.h };
  });
  const minX = Math.min(...rects.map(item => item.x));
  const minY = Math.min(...rects.map(item => item.y));
  const maxX = Math.max(...rects.map(item => item.x + item.w));
  const maxY = Math.max(...rects.map(item => item.y + item.h));
  const graphW = Math.max(1, maxX - minX);
  const graphH = Math.max(1, maxY - minY);
  const scale = Math.min(620 / graphW, 300 / graphH);
  const offsetX = 50 + (620 - graphW * scale) / 2;
  const offsetY = 80 + (300 - graphH * scale) / 2;
  const point = item => ({
    x: offsetX + (item.x - minX) * scale,
    y: offsetY + (item.y - minY) * scale,
    w: Math.max(24, item.w * scale),
    h: Math.max(18, item.h * scale)
  });
  const byId = new Map(rects.map(item => [item.node.id, item]));
  ctx.strokeStyle = SELECT_BLUE;
  ctx.lineWidth = 2;
  (graph.edges || []).forEach(edge => {
    const from = byId.get(edge.from);
    const to = byId.get(edge.to);
    if (!from || !to) return;
    const a = point(from), b = point(to);
    const x1 = a.x + a.w, y1 = a.y + a.h / 2;
    const x2 = b.x, y2 = b.y + b.h / 2;
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.bezierCurveTo(x1 + 34, y1, x2 - 34, y2, x2, y2);
    ctx.stroke();
  });
  const colors = {
    generator: ['#dbe7f0', '#56788f'], image: ['#ebe6df', '#6f675e'], variant: ['#e7eee8', '#5e7864'],
    material: ['#f1e7d8', '#8a6845'], light: ['#f5efc9', '#887b2e'], param: ['#e5e7ee', '#5f6686'],
    tool: ['#e8e1ef', '#6f5b86'], layout: ['#e2eceb', '#4f7470'], soft: ['#f0e3df', '#8a5d55'],
    error: ['#f3dddd', '#945050'], note: ['#efeee8', '#716f66'], collapsed: ['#e1e9ec', '#557582']
  };
  rects.forEach(item => {
    const r = point(item);
    const palette = colors[item.node.type] || ['#e9e7e2', '#5f5b55'];
    ctx.fillStyle = palette[0];
    ctx.strokeStyle = palette[1];
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    if (ctx.roundRect) ctx.roundRect(r.x, r.y, r.w, r.h, 8);
    else ctx.rect(r.x, r.y, r.w, r.h);
    ctx.fill();
    ctx.stroke();
    ctx.fillStyle = palette[1];
    ctx.font = '600 ' + Math.max(8, Math.min(13, r.w * 0.08)) + 'px "GIWIN Sans",sans-serif';
    const label = item.node.label || item.node.type || '节点';
    ctx.fillText(fitCanvasText(ctx, label, r.w - 12), r.x + 6, r.y + Math.max(14, r.h * 0.38));
  });
  ctx.fillStyle = '#272522';
  ctx.font = '700 25px "GIWIN Serif",serif';
  ctx.fillText(fitCanvasText(ctx, title || '工作流资产', 600), 50, 43);
  ctx.fillStyle = '#8b857d';
  ctx.font = '400 12px "GIWIN Sans",sans-serif';
  ctx.fillText(graph.nodes.length + ' 个节点 · ' + (graph.edges || []).length + ' 条连线', 50, 63);
  return canvas.toDataURL('image/jpeg', 0.86);
}
async function captureAssetPreview(options = {}) {
  const kind = options.kind === 'workflow' ? 'workflow' : 'asset';
  if (kind === 'workflow') return buildWorkflowPreviewDataURL(options.graph, options.name || '工作流资产');
  const picked = selection();
  const pickedImage = picked.find(k => k.gwType === 'variant' || (k.getClassName && k.getClassName() === 'Image'));
  if (pickedImage) {
    const k = pickedImage.konva || pickedImage;
    let source = k.gwType === 'variant' ? cardPreviewDataURL(k, 900) : displayThumbDataURL(k);
    if (source) {
      try {
        const image = await loadImageElement(source);
        const canvas = document.createElement('canvas');
        canvas.width = 720; canvas.height = 420;
        drawImageCoverRect(canvas.getContext('2d'), image, 0, 0, 720, 420);
        return canvas.toDataURL('image/jpeg', 0.86);
      } catch (error) {}
    }
  }
  const recipe = options.recipe || {};
  const subtitle = [recipe.styleName, recipe.model, recipe.size, recipe.aspect].filter(Boolean).join(' · ');
  return assetPreviewPlaceholder(options.name || recipe.styleName || '通用资产', subtitle, kind);
}
async function captureWorkflowCompositePreview() {
  const picked = selection();
  if (!picked.length) return '';
  const savedView = {
    x: stage.x(),
    y: stage.y(),
    scale: stage.scaleX(),
    trVisible: tr ? tr.visible() : false,
    portVisible: portLayer ? portLayer.visible() : true,
    gridVisible: gridLayer ? gridLayer.visible() : true
  };
  const savedGridCanvasVisibility = bgCanvas ? bgCanvas.style.visibility : '';
  const hiddenDom = [];
  const hideDom = selector => {
    const element = document.querySelector(selector);
    if (!element || element.style.visibility === 'hidden') return;
    hiddenDom.push({ element, visibility: element.style.visibility });
    element.style.visibility = 'hidden';
  };
  try {
    const worldRects = picked.map(k => visualNodeRect(k)).filter(Boolean);
    if (!worldRects.length) return '';
    const minX = Math.min(...worldRects.map(rect => rect.x));
    const minY = Math.min(...worldRects.map(rect => rect.y));
    const maxX = Math.max(...worldRects.map(rect => rect.x + rect.width));
    const maxY = Math.max(...worldRects.map(rect => rect.y + rect.height));
    const worldW = Math.max(1, maxX - minX);
    const worldH = Math.max(1, maxY - minY);
    const margin = 72;
    const scale = Math.min(
      1,
      Math.max(0.08, (stage.width() - margin * 2) / worldW),
      Math.max(0.08, (stage.height() - margin * 2) / worldH)
    );
    const centerX = minX + worldW / 2;
    const centerY = minY + worldH / 2;
    stage.scale({ x: scale, y: scale });
    stage.position({
      x: stage.width() / 2 - centerX * scale,
      y: stage.height() / 2 - centerY * scale
    });
    syncPanelsWorldTransform();
    if (tr) tr.visible(false);
    if (portLayer) portLayer.visible(false);
    if (gridLayer) gridLayer.visible(false);
    if (bgCanvas) bgCanvas.style.visibility = 'hidden';
    setSelection([], true);
    hideDom('#gw-rail');
    hideDom('#island');
    hideDom('#side-left');
    hideDom('#drawer-scrim');
    hideDom('.canvas-shortcut-hints');
    await Promise.all(picked.map(k => applyNodeQuality(k, 1024).catch(() => {})));
    drawGrid();
    mainLayer.draw();
    await new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(resolve)));
    const stageRect = stage.container().getBoundingClientRect();
    const clientRects = picked.map(k => {
      const panel = persistentNodePanels.get(k.gwId);
      if (panel && panel.panel) return panel.panel.getBoundingClientRect();
      const rect = visualNodeRect(k);
      if (!rect) return null;
      return {
        left: stageRect.left + stage.x() + rect.x * scale,
        top: stageRect.top + stage.y() + rect.y * scale,
        right: stageRect.left + stage.x() + (rect.x + rect.width) * scale,
        bottom: stageRect.top + stage.y() + (rect.y + rect.height) * scale
      };
    }).filter(Boolean);
    if (!clientRects.length) return '';
    const padding = 12;
    const left = Math.max(0, Math.min(...clientRects.map(rect => rect.left)) - padding);
    const top = Math.max(0, Math.min(...clientRects.map(rect => rect.top)) - padding);
    const right = Math.min(window.innerWidth, Math.max(...clientRects.map(rect => rect.right)) + padding);
    const bottom = Math.min(window.innerHeight, Math.max(...clientRects.map(rect => rect.bottom)) + padding);
    const result = await ipcRenderer.invoke('capture:pageRegion', {
      rect: { x: left, y: top, width: Math.max(1, right - left), height: Math.max(1, bottom - top) }
    });
    return result && result.ok ? result.dataURL : '';
  } catch (error) {
    console.warn('[workflow preview]', error.message);
    return '';
  } finally {
    stage.position({ x: savedView.x, y: savedView.y });
    stage.scale({ x: savedView.scale, y: savedView.scale });
    if (tr) tr.visible(savedView.trVisible);
    if (portLayer) portLayer.visible(savedView.portVisible);
    if (gridLayer) gridLayer.visible(savedView.gridVisible);
    if (bgCanvas) bgCanvas.style.visibility = savedGridCanvasVisibility;
    if (persistentNodePanels.size) syncPanelsWorldTransform();
    hiddenDom.forEach(item => { item.element.style.visibility = item.visibility; });
    setSelection(picked, true);
    drawGrid();
    mainLayer.batchDraw();
    refreshGraphPorts();
    scheduleViewportSettle(0);
  }
}
async function instantiateNodeRecord(nd) {
  if (nd.type === 'note') {
    const group = buildNoteGroup(nd);
    if (nd.rotation) group.rotation(nd.rotation);
    if (nd.sx) group.scaleX(nd.sx);
    if (nd.sy) group.scaleY(nd.sy);
    mainLayer.add(group);
    nodes.push({ id: nd.id, type: 'note', konva: group });
    bindNoteEvents(group);
    return group;
  }
  if (nd.type === 'image') {
    // src 可能是项目内文件名，也可能是内联 data:/blob:/http 地址（模板占位图等）。
    // 后三种不能走 img:read（那是按项目内文件名读盘的），否则节点会静默创建失败。
    const srcText = String(nd.src || '');
    let el;
    if (!srcText) el = mediaPlaceholderCanvas();
    else if (/^(?:data:image\/|blob:|https?:\/\/)/i.test(srcText)) el = await loadImageElement(srcText);
    else el = await getDisplayImage(srcText, 128);
    if (!nd.ow) nd.ow = el._gwNaturalWidth || el.naturalWidth || el.width;
    if (!nd.oh) nd.oh = el._gwNaturalHeight || el.naturalHeight || el.height;
    const node = await createImageNode(nd, el);
    if (nd.star) { node.gwStar = true; syncStarBadge(node); }
    return node;
  }
  if (nd.type === 'variant') return rebuildVariant(nd);
  if (nd.type === 'tool') return rebuildToolNode(nd);
  if (nd.type === 'material') return rebuildMaterialNode(nd);
  if (nd.type === 'light') return rebuildLightNode(nd);
  if (nd.type === 'compare') return rebuildCompareNode(nd);
  if (nd.type === 'generator') {
    const group = buildGeneratorGroup(nd);
    mainLayer.add(group);
    nodes.push({ id: nd.id, type: 'generator', konva: group });
    bindGeneratorNodeEvents(group);
    return group;
  }
  if (nd.type === 'param') {
    const group = buildParamGroup(nd);
    mainLayer.add(group);
    nodes.push({ id: nd.id, type: 'param', konva: group });
    bindParamNodeEvents(group);
    return group;
  }
  if (nd.type === 'collapsed') return rebuildCollapsedNode(nd);
  if (nd.type === 'error') {
    rebuildErrorNode(nd);
    const rec = nodes.find(item => item.id === nd.id);
    return rec ? rec.konva : null;
  }
  return null;
}
async function instantiateTemplate(template, at, options) {
  if (!template || !Array.isArray(template.nodes) || !template.nodes.length) {
    throw new Error('工作流模板为空');
  }
  const capture = beginCreationCapture();
  const center = centerWorld();
  const baseX = at ? at.x : center[0] - 80;
  const baseY = at ? at.y : center[1] - 80;
  const stamp = Date.now().toString(36) + Math.random().toString(36).slice(2, 4);
  const idMap = {};
  template.nodes.forEach((nd, index) => { idMap[nd.id] = 'tpl' + stamp + index; });
  const remap = id => idMap[id] || id;
  const created = [];
  for (const original of template.nodes) {
    const nd = JSON.parse(JSON.stringify(original));
    nd.id = idMap[original.id];
    nd.x = (original.x || 0) + baseX;
    nd.y = (original.y || 0) + baseY;
    if (nd.source) nd.source = remap(nd.source);
    if (nd.sourceId) nd.sourceId = remap(nd.sourceId);
    if (Array.isArray(nd.markCameras)) {
      nd.markCameras.forEach(camera => {
        if (camera && camera.sourceId) camera.sourceId = remap(camera.sourceId);
      });
    }
    if (nd.refId) nd.refId = remap(nd.refId);
    if (nd.genId) nd.genId = remap(nd.genId);
    try {
      const node = await instantiateNodeRecord(nd);
      if (node) created.push(node);
    } catch (error) {
      console.warn('[template] 节点实例化失败', nd.type, error.message);
    }
  }
  const edges = (template.edges || [])
    .filter(edge => idMap[edge.from] && idMap[edge.to])
    .map((edge, index) => ({
      ...edge,
      id: 'tple' + stamp + index,
      from: idMap[edge.from],
      to: idMap[edge.to]
    }));
  restoreEdgeRecords(edges);
  if (created.length) setSelection(created, true);
  afterMutation(((options && options.label) || '已调用工作流模板') + ' · ' + created.length + ' 个节点');
  commitCreationCapture(capture, '调用工作流模板');
  return created;
}
// 把一段 dataURL 写进当前项目的 Content 目录，返回项目内文件名。
// 模板占位图走这条路，节点就和手动导入的图片完全一致（可连端口、可保存、可被替换）。
async function saveProjectImageDataURL(dataURL) {
  if (!project || !project.path) throw new Error('请先打开项目');
  const result = await ipcRenderer.invoke('img:write', { projectPath: project.path, dataURL });
  if (!result || !result.ok) throw new Error((result && result.msg) || '图片保存失败');
  return { name: result.name, w: result.w, h: result.h };
}
function createRenderWorkflowFromIds(sourceIds, paramsOverride, options = {}) {
  if (!project) throw new Error('请先打开项目');
  const ids = Array.from(new Set((sourceIds || []).filter(Boolean)));
  const sources = ids
    .map(id => nodes.find(record => record.id === id))
    .filter(record => record && record.konva && record.konva.getStage && isMediaConnectionSource(record.konva));
  if (!sources.length) throw new Error('没有可用的图片节点');
  const chunks = [];
  for (let index = 0; index < sources.length; index += 4) {
    chunks.push(sources.slice(index, index + 4));
  }
  const minX = Math.min(...sources.map(record => record.konva.x()));
  const maxRight = Math.max(...sources.map(record => {
    const size = layoutNodeSize(record.konva);
    return record.konva.x() + size.w;
  }));
  const centerY = sources.reduce((sum, record) => {
    const size = layoutNodeSize(record.konva);
    return sum + record.konva.y() + size.h / 2;
  }, 0) / sources.length;
  const createIds = [];
  chunks.forEach((chunk, index) => {
    setSelection(chunk.map(record => record.konva), true);
    const requested = options.positions && options.positions[index];
    const at = requested || {
      x: Math.max(minX + 320, maxRight + 150),
      y: centerY - GENERATOR_H / 2 + index * (GENERATOR_H + 90)
    };
    const generator = createGeneratorNode(chunk[0].konva, at, paramsOverride, { silentAfter: true });
    if (generator) {
      generator.gwCopilotPlanId = options.planId || '';
      generator.gwRunGroupId = options.groupId || '';
      createIds.push(generator.gwId);
    }
  });
  if (!createIds.length) throw new Error('工作流未能创建生成节点');
  const created = createIds
    .map(id => nodes.find(record => record.id === id))
    .filter(record => record && record.konva)
    .map(record => record.konva);
  setSelection(created, true);
  if (!options.silent) {
    afterMutation('Copilot 已创建 ' + createIds.length + ' 个生成批次 · 共接入 ' + sources.length + ' 张图片');
  }
  return {
    generatorIds: createIds,
    sourceCount: sources.length,
    batchCount: createIds.length
  };
}
function createSoftWorkflowFromIds(sourceIds, options = {}) {
  const sources = Array.from(new Set(sourceIds || []))
    .map(id => nodes.find(record => record.id === id))
    .filter(record => record && record.konva && isMediaConnectionSource(record.konva));
  if (!sources.length) throw new Error('没有可用于软装提取的图片');
  const chunks = [];
  for (let index = 0; index < sources.length; index += 8) {
    chunks.push(sources.slice(index, index + 8));
  }
  const maxRight = Math.max(...sources.map(record => record.konva.x() + layoutNodeSize(record.konva).w));
  const centerY = sources.reduce((sum, record) => sum + record.konva.y() + layoutNodeSize(record.konva).h / 2, 0) / sources.length;
  const softIds = [];
  chunks.forEach((chunk, index) => {
    setSelection(chunk.map(record => record.konva), true);
    const group = createSoftNode({
      x: maxRight + 140,
      y: centerY - SOFT_H / 2 + index * (SOFT_H + 70)
    }, { silentAfter: true, openEditor: false });
    if (group) {
      group.gwCopilotPlanId = options.planId || '';
      softIds.push(group.gwId);
    }
  });
  if (!softIds.length) throw new Error('未能创建软装提取节点');
  const groups = softIds.map(id => nodes.find(record => record.id === id)).filter(Boolean).map(record => record.konva);
  setSelection(groups, true);
  return { softIds, sourceCount: sources.length, batchCount: softIds.length };
}

function createLayoutWorkflowFromIds(sourceIds, softIds, options = {}) {
  const media = Array.from(new Set(sourceIds || []))
    .map(id => nodes.find(record => record.id === id))
    .filter(record => record && record.konva && isMediaConnectionSource(record.konva));
  const softRecords = Array.from(new Set(softIds || []))
    .map(id => nodes.find(record => record.id === id))
    .filter(record => record && record.konva && record.konva.gwType === 'soft');
  if (!media.length && !softRecords.length) throw new Error('没有可用于排版的图片或软装数据');
  if (media.length) setSelection(media.map(record => record.konva), true);
  else setSelection([softRecords[0].konva], true);
  const overlap = media.length ? media : softRecords;
  const maxRight = Math.max(...overlap.map(record => record.konva.x() + layoutNodeSize(record.konva).w));
  const centerY = overlap.reduce((sum, record) => sum + record.konva.y() + layoutNodeSize(record.konva).h / 2, 0) / overlap.length;
  const layout = createLayoutNode({
    x: maxRight + 150,
    y: centerY - LAYOUT_H / 2
  }, media.length ? null : softRecords[0].konva, { silentAfter: true, openEditor: false });
  if (!layout) throw new Error('未能创建版式输出节点');
  softRecords.forEach(record => {
    try { createGraphEdge(record.konva, layout, 'soft'); } catch (error) {}
  });
  layout.gwCopilotPlanId = options.planId || '';
  setSelection([layout], true);
  return { layoutId: layout.gwId, sourceCount: media.length, softCount: softRecords.length };
}
async function runGeneratorById(id, statusEl) {
  const record = nodes.find(node => node.id === id);
  if (!record || !record.konva) return { ok: false, error: '生成节点不存在' };
  if (record.konva.gwRunning) return { ok: false, error: '生成节点正在运行' };
  record.konva.gwLastRunCancelled = false;
  const before = new Set(nodes.filter(node =>
    node.konva && node.konva.gwGenerationContext &&
    node.konva.gwGenerationContext.generatorId === id
  ).map(node => node.id));
  await runGeneratorNode(record.konva, statusEl || null);
  const created = nodes.filter(node =>
    node.konva && node.konva.gwGenerationContext &&
    node.konva.gwGenerationContext.generatorId === id &&
    !before.has(node.id)
  );
  return {
    ok: created.length > 0,
    cancelled: !!record.konva.gwLastRunCancelled,
    generatorId: id,
    created: created.length,
    resultIds: created.map(node => node.id)
  };
}
function cancelGeneratorById(id) {
  const record = nodes.find(node => node.id === id);
  if (!record || !record.konva) return false;
  try {
    record.konva.gwCancelRequested = true;
    if (record.konva.gwRunController) record.konva.gwRunController.abort();
    return true;
  } catch (error) {
    return false;
  }
}

async function runUpscaleByIds(sourceIds, resolution, onStatus, options = {}) {
  const sources = Array.from(new Set(sourceIds || []))
    .map(id => nodes.find(record => record.id === id))
    .filter(record => record && record.konva && (record.konva.gwType === 'variant' || record.konva.getClassName() === 'Image'))
    .map(record => record.konva);
  if (!sources.length) throw new Error('没有可用于高清放大的图片');
  return runHdUpscale(sources, resolution || '2k', onStatus, options);
}

async function runLayoutCopyById(id, options = {}) {
  const record = nodes.find(node => node.id === id);
  if (!record || !record.konva || record.konva.gwType !== 'layout') throw new Error('版式输出节点不存在');
  const g = record.konva;
  if (!Array.isArray(g.gwLayout.items) || !g.gwLayout.items.length) {
    if (!String(g.gwLayout.concept || '').trim()) {
      g.gwLayout.concept = '以软装选品与空间材质为线索，整理材质、色彩、灯光和生活方式的整体关系。';
    }
    refreshLayoutNode(g);
    afterMutation('软装选品页已更新');
    return {
      status: 'success',
      conceptGenerated: false,
      pages: layoutPagePlan(g.gwLayout, softConfigsForLayout(g)).length,
      failedPages: 0
    };
  }
  const target = softVisionTarget(g, options.choice || null);
  if (!target) throw new Error('请先配置可用的方案文案视觉模型');
  if (typeof options.onStatus === 'function') options.onStatus('正在生成设计概念与页面文案…');
  const result = await generateLayoutBookCopy(g.gwLayout, target, options.onStatus);
  g.gwLayout.concept = result.concept;
  refreshLayoutNode(g);
  afterMutation('版式输出文案已更新 · ' + result.total + ' 页');
  return {
    status: 'success',
    conceptGenerated: true,
    pages: result.total,
    failedPages: result.failed
  };
}

function workflowNodeDescriptor(id) {
  const record = nodes.find(node => node.id === id);
  if (!record || !record.konva) return null;
  const k = record.konva;
  const base = { id, type: record.type, executionMode: 'auto' };
  if (['image', 'variant', 'param', 'material', 'light', 'note'].includes(record.type)) {
    return Object.assign(base, { executionMode: 'data', label: k.gwLabel || record.type });
  }
  if (record.type === 'generator') {
    const generatorMode = normalizeDesignMode(k.gwParams && k.gwParams.designMode);
    const modeLabel = generatorMode === DESIGN_MODE_PLAN
      ? '平面表现'
      : (generatorMode === DESIGN_MODE_CONCEPT ? '概念效果图' : '空间渲染');
    return Object.assign(base, { label: k.gwTextOnly ? '文生图' : modeLabel });
  }
  if (record.type === 'soft') {
    return Object.assign(base, { label: '软装提取与选品', requiresReview: true });
  }
  if (record.type === 'layout') {
    return Object.assign(base, { label: '版式输出' });
  }
  if (record.type === 'tool') {
    const kind = k.gwToolKind || '';
    const markReady = kind === 'mark' && Array.isArray(k.gwMarkCameras) &&
      k.gwMarkCameras.length > 0 && k.gwMarkCameras.every(camera => !!camera.result);
    const resultReady = ['reverse', 'chat'].includes(kind) && !!String(k.gwToolResult || '').trim();
    const manual = ['mark', 'inpaint', 'reverse', 'chat'].includes(kind) && !markReady && !resultReady;
    return Object.assign(base, {
      executionMode: manual ? 'manual' : 'auto',
      label: k.gwToolLabel || '图像工具',
      toolKind: kind,
      manualReason: kind === 'mark'
        ? (markReady ? '' : '请先在标记节点完成标记并保存')
        : (kind === 'inpaint' ? '请先完成局部选区' : '该工具需要人工输入')
    });
  }
  if (record.type === 'collapsed') {
    return Object.assign(base, { executionMode: 'manual', manualReason: '请先展开合并节点再运行' });
  }
  return Object.assign(base, { executionMode: 'manual', manualReason: '当前节点不支持自动执行' });
}

async function runWorkflowNodeById(id, options = {}) {
  const record = nodes.find(node => node.id === id);
  if (!record || !record.konva) throw new Error('工作流节点不存在');
  const k = record.konva;
  if (record.type === 'image' || record.type === 'variant' || record.type === 'param' ||
      record.type === 'material' || record.type === 'light' || record.type === 'note') {
    return { status: 'success', message: '输入已就绪' };
  }
  if (record.type === 'generator') {
    if (k.gwTextOnly) {
      await runTextToImageNode(k, options.statusEl || null);
      return { status: 'success', message: '文生图已完成' };
    }
    const result = await runGeneratorById(id, options.statusEl || null);
    return {
      status: result.ok ? 'success' : (result.cancelled ? 'cancelled' : 'failed'),
      message: result.ok ? '已生成 ' + result.created + ' 张' : (result.cancelled ? '生成已取消' : '生成未返回结果'),
      created: result.created || 0,
      resultIds: result.resultIds || []
    };
  }
  if (record.type === 'soft') {
    const existingItems = Array.isArray(k.gwSoft && k.gwSoft.items) ? k.gwSoft.items : [];
    if (existingItems.length && !options.forceSoft) {
      const allConfirmed = existingItems.every(item => !!item.confirmed);
      return {
        status: allConfirmed ? 'success' : 'waiting',
        message: allConfirmed ? '软装已确认，进入下游排版' : '软装清单已经存在，等待人工确认',
        requiresReview: !allConfirmed
      };
    }
    const result = await extractSoftItemsForNode(k, {
      onStatus: options.onStatus
    });
    return {
      status: 'waiting',
      message: '软装已提取，等待人工确认',
      result,
      requiresReview: true
    };
  }
  if (record.type === 'layout') {
    return runLayoutCopyById(id, options);
  }
  if (record.type === 'tool' && k.gwToolKind === 'upscale-local') {
    const sourceEdge = graphEdgeValues().find(edge => edge.to === id && edge.port === 'image');
    if (!sourceEdge) throw new Error('高清放大节点没有来源图片');
    const factor = Math.max(2, Number(k.gwUpscaleFactor) || 2);
    await runInlineUpscale(k, factor);
    return { status: 'success', message: '本地高清放大已完成' };
  }
  if (record.type === 'tool' && k.gwToolKind === 'mark') {
    const cameras = Array.isArray(k.gwMarkCameras) ? k.gwMarkCameras : [];
    if (cameras.length && cameras.every(camera => !!camera.result)) {
      return { status: 'success', message: '标记结果已确认' };
    }
    return { status: 'waiting', message: '请先在标记节点完成标记并保存' };
  }
  if (record.type === 'tool' && ['reverse', 'chat'].includes(k.gwToolKind) && String(k.gwToolResult || '').trim()) {
    return { status: 'success', message: '工具结果已存在' };
  }
  const descriptor = workflowNodeDescriptor(id);
  return {
    status: 'waiting',
    message: descriptor && descriptor.manualReason || '等待人工操作'
  };
}

async function runWorkflowByIds(sourceIds, options = {}) {
  if (!window.GWWorkflowRuntime) throw new Error('工作流调度器未加载');
  let ids = Array.from(new Set((sourceIds || []).filter(Boolean)));
  const collapsed = ids
    .map(id => nodes.find(node => node.id === id))
    .filter(record => record && record.type === 'collapsed');
  for (const record of collapsed) {
    await expandCollapsedCard(record.konva);
    const expandedIds = selection().map(k => k.gwId).filter(Boolean);
    ids = ids.filter(id => id !== record.id).concat(expandedIds);
  }
  ids = Array.from(new Set(ids));
  const state = serialize();
  const scopeNodes = state.nodes
    .filter(node => ids.includes(node.id))
    .map(node => {
      const descriptor = workflowNodeDescriptor(node.id);
      return descriptor || { id: node.id, type: node.type, executionMode: 'data' };
    });
  if (!scopeNodes.length) throw new Error('没有可运行的工作流节点');
  return window.GWWorkflowRuntime.runDag({
    nodes: scopeNodes,
    edges: state.edges || [],
    nodeIds: scopeNodes.map(node => node.id),
    shouldStop: options.shouldStop,
    onEvent: event => {
      if (typeof options.onProgress === 'function') options.onProgress(event);
    },
    execute: node => runWorkflowNodeById(node.id, {
      statusEl: options.statusEl,
      onStatus: text => {
        if (typeof options.onNodeStatus === 'function') options.onNodeStatus(node.id, text);
      },
      choice: options.choice,
      forceSoft: !!options.forceSoft
    })
  });
}

