function readCosts() {
  try { return JSON.parse(localStorage.getItem('gw_costs') || '[]'); } catch (e) { return []; }
}
function addCost(engineId, n, unit, model) {
  const log = readCosts();
  log.push({ t: Date.now(), engine: engineId, n: n, cost: +(unit * n).toFixed(2), model: model || '' });
  localStorage.setItem('gw_costs', JSON.stringify(log.slice(-300)));
}

/* ---------- 配方面板 ---------- */
function renderModelPicker(container, opts) {
  if (!container) return;
  const P = window.GWProviders;
  const engineId = opts.engineId;
  const models = (opts.models || []).slice();
  const current = opts.current || models[0] || '';
  const currentMeta = P && P.vendorMeta ? P.vendorMeta(engineId, current) : { id: 'generic', label: '其他', logo: 'logos/generic.svg' };
  const currentLabel = P && P.aliasOf ? P.aliasOf(current) : current;
  const currentKnown = P && P.isRegisteredModel ? P.isRegisteredModel(engineId, current) : true;
  container.innerHTML = `
    <button type="button" class="gw-model-btn">
      <img class="gw-vendor-logo" src="${esc(currentMeta.logo)}" alt="">
      <span class="gw-model-current">${esc(currentLabel || '选择模型')}${currentKnown ? '' : ' ⚠'}</span>
      <span class="gw-caret">▾</span>
    </button>
    <div class="gw-model-menu hidden"></div>`;
  const btn = container.querySelector('.gw-model-btn');
  const menu = container.querySelector('.gw-model-menu');
  const groups = new Map();
  models.forEach(m => {
    const meta = P && P.vendorMeta ? P.vendorMeta(engineId, m) : { id: 'generic', label: '其他', logo: 'logos/generic.svg' };
    if (!groups.has(meta.id)) groups.set(meta.id, { meta, list: [] });
    groups.get(meta.id).list.push(m);
  });
  menu.innerHTML = [...groups.values()].map(g => `
    <div class="gw-vendor-group">
      <div class="gw-vendor-head"><img class="gw-vendor-logo" src="${esc(g.meta.logo)}" alt=""><span>${esc(g.meta.label)}</span><span class="gw-vendor-count">${g.list.length}</span></div>
      ${g.list.map(m => {
        const meta = P && P.vendorMeta ? P.vendorMeta(engineId, m) : g.meta;
        const known = P && P.isRegisteredModel ? P.isRegisteredModel(engineId, m) : true;
        const label = (P && P.aliasOf ? P.aliasOf(m) : m) + (known ? '' : ' ⚠');
        return `<button type="button" class="gw-model-option ${m === current ? 'on' : ''}" data-model="${esc(m)}"><img class="gw-vendor-logo" src="${esc(meta.logo)}" alt=""><span>${esc(label)}</span>${known ? '' : '<span class="gw-unknown">未登记</span>'}</button>`;
      }).join('')}
    </div>`).join('');
  const rect = container.getBoundingClientRect();
  menu.classList.toggle('up', (window.innerHeight - rect.bottom) < 280);
  btn.onclick = e => { e.stopPropagation(); menu.classList.toggle('hidden'); };
  // 统一键盘行为：↑↓ 移动高亮 / Enter 确认 / Esc 关闭
  let kbIndex = -1;
  const optionList = () => Array.from(menu.querySelectorAll('.gw-model-option'));
  const setKbFocus = index => {
    const list = optionList();
    if (!list.length) { kbIndex = -1; return; }
    kbIndex = Math.max(0, Math.min(list.length - 1, index));
    list.forEach((opt, i) => opt.classList.toggle('kb-focus', i === kbIndex));
    if (list[kbIndex]) list[kbIndex].scrollIntoView({ block: 'nearest' });
  };
  container.addEventListener('keydown', e => {
    if (menu.classList.contains('hidden')) {
      if ((e.key === 'ArrowDown' || e.key === 'Enter') && document.activeElement === btn) {
        e.preventDefault();
        menu.classList.remove('hidden');
        setKbFocus(0);
      }
      return;
    }
    if (e.key === 'Escape') { e.stopPropagation(); menu.classList.add('hidden'); if (btn.focus) btn.focus(); }
    else if (e.key === 'ArrowDown') { e.preventDefault(); setKbFocus(kbIndex + 1); }
    else if (e.key === 'ArrowUp') { e.preventDefault(); setKbFocus(kbIndex - 1); }
    else if (e.key === 'Enter') { e.preventDefault(); const list = optionList(); if (kbIndex >= 0 && list[kbIndex]) list[kbIndex].click(); }
  });
  container.onclick = e => {
    const opt = e.target.closest && e.target.closest('.gw-model-option');
    if (!opt) return;
    e.stopPropagation();
    const m = opt.getAttribute('data-model');
    if (m && opts.onSelect) opts.onSelect(m);
  };
}
const MATERIAL_W = 320, MATERIAL_H = NODE_CARD_H;
