  rug: ['浅灰短绒地毯', '米白羊毛地毯', '灰色编织地毯', '深色长绒地毯', '几何图案地毯'],
  wall: ['白色乳胶漆', '米白微水泥', '浅灰艺术漆', '胡桃木饰面', '木格栅', '石材墙面', '布艺软包', '素色壁纸'],
  skirting: ['白色踢脚线', '浅木色踢脚线', '深木色踢脚线', '金属踢脚线', '黑色极窄踢脚线', '石材踢脚线'],
