  const images = [];
  for (const entry of entries) {
    try {
      const dataURL = await getImageRuntime().readDataURL(entry.src);
      if (!dataURL) continue;
      const referenceURL = entry.tintFollow && entry.color
        ? await tintedMaterialReferenceDataURL(
          entry.src,
          entry.color,
          entry.tintStrength,
          768,
          {
            hueShift: entry.hueShift,
            saturation: entry.saturation,
            lightnessOffset: entry.lightnessOffset
          }
        )
        : dataURL;
      const image = await new Promise((resolve, reject) => {
        const img = new Image();
        img.onload = () => resolve(img);
        img.onerror = reject;
        img.src = referenceURL || dataURL;
      });
      images.push({ image, label: (images.length + 1) + '. ' + entry.label + ' · ' + entry.name });
    } catch (error) {
      console.warn('[material] 参考图读取失败', entry.src, error.message);
    }
  }
