    wall: 'wall', '墙面': 'wall', skirting: 'skirting', '踢脚线': 'skirting',
    cabinet: 'cabinet', '柜体': 'cabinet', ceiling: 'ceiling', '吊顶': 'ceiling',
    door: 'door', '房门': 'door', glass: 'glass', '玻璃': 'glass',
    sofa: 'sofa', '沙发': 'sofa', cushion: 'cushion', '靠枕': 'cushion', '抱枕': 'cushion',
