async function cropMaterialReference(dataURL, box, label) {
  if (!project || !dataURL || !Array.isArray(box) || box.length !== 4) return null;
  let values = box.map(Number);
  if (values.some(value => !Number.isFinite(value))) return null;
  if (Math.max(...values) > 1 && Math.max(...values) <= 100) values = values.map(value => value / 100);
  if (Math.min(...values) < 0 || Math.max(...values) > 1) return null;
  let [x1, y1, x2, y2] = values;
  if (x1 > x2) [x1, x2] = [x2, x1];
  if (y1 > y2) [y1, y2] = [y2, y1];
  const area = (x2 - x1) * (y2 - y1);
  if (area < 0.002 || area > 0.92) return null;
  const image = await new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => resolve(img);
    img.onerror = reject;
    img.src = dataURL;
  });
  const iw = image.naturalWidth || image.width;
  const ih = image.naturalHeight || image.height;
  const padX = Math.max(0.004, (x2 - x1) * 0.03);
  const padY = Math.max(0.004, (y2 - y1) * 0.03);
  x1 = Math.max(0, x1 - padX); y1 = Math.max(0, y1 - padY);
  x2 = Math.min(1, x2 + padX); y2 = Math.min(1, y2 + padY);
  const sx = Math.round(x1 * iw), sy = Math.round(y1 * ih);
  const sw = Math.max(1, Math.min(iw - sx, Math.round((x2 - x1) * iw)));
  const sh = Math.max(1, Math.min(ih - sy, Math.round((y2 - y1) * ih)));
  const scale = Math.min(1, 512 / Math.max(sw, sh));
  const canvas = document.createElement('canvas');
  canvas.width = Math.max(1, Math.round(sw * scale));
  canvas.height = Math.max(1, Math.round(sh * scale));
  canvas.getContext('2d').drawImage(image, sx, sy, sw, sh, 0, 0, canvas.width, canvas.height);
  const saved = await ipcRenderer.invoke('img:write', {
    projectPath: project.path,
    dataURL: canvas.toDataURL('image/jpeg', 0.9)
  });
  if (!saved || !saved.ok) return null;
  return { src: saved.name, name: 'AI · ' + label, w: saved.w || canvas.width, h: saved.h || canvas.height, at: Date.now() };
}
