    presetId: preset.id,
    name: preset.name,
    intensity: preset.intensity,
    temperature: preset.temperature,
    softness: preset.softness,
    direction: preset.direction,
    weather: '晴天',
    lightingMode: 'auto',
    lightingGroups: LIGHT_FIXTURE_GROUPS.map(item => item.id),
    note: '',
    exteriorAffectLight: true,
    exteriorPreset: 'original',
    exteriorName: '保留原图',
    exteriorPrompt: '',
    exterior: null
