  const usedCount = (ref && refNode) ? nodes.filter(n => n.type === 'variant' && n.konva.gwId !== ref.nodeId && n.konva.gwRoom === room && n.konva.gwRefVersion === ref.version).length : 0;
  const mixedRooms = sel && sel.length > 1 && new Set(sel.map(k => k.gwRoom).filter(Boolean)).size > 1;
  const roomMaterial = materialsForRoom(room) || {};
